describe('Audit findings requiring product review', () => {
  it('switch booking language after entering details → customer draft should survive', () => {
    cy.get('@seed').then((seed) => {
      cy.visit(`/book/?lang=en&service=${seed.services.cut}&barber=${seed.barbers.alan}&date=${seed.date}&time=09:00`);
      cy.get('#details [name="customer_name"]').type('Synthetic Language Draft');
      cy.get('#details [name="phone"]').type('0888123456');
      cy.task('db:snapshot').then((before) => {
        cy.get('a[lang="bg"]').click();
        cy.get('html').should('have.attr', 'lang', 'bg');
        cy.assertNoBusinessChange(before);
        cy.get('#details [name="customer_name"]').should('have.value', 'Synthetic Language Draft');
        cy.get('#details [name="phone"]').should('have.value', '0888123456');
      });
    });
  });

  it('catalogue quote changes before confirmation → review reconfirmation before booking at changed price', () => {
    cy.get('@seed').then((seed) => {
      cy.visit(`/book/?lang=en&service=${seed.services.cut}&barber=${seed.barbers.alan}&date=${seed.date}&time=09:00`);
      cy.get('#details').should('contain', '20.00 EUR').and('contain', '30');
      cy.get('#details [name="customer_name"]').type('Synthetic Stale Quote');
      cy.get('#details [name="phone"]').type('0888123456');
      cy.task('db:changeQuote');
      cy.get('#details button').click();
      cy.task('db:snapshot').then((after) => {
        // Review recommendation, not an agreed requirement: request acceptance
        // of the changed quote before creating the reservation.
        const changed = after.appointments.filter((row) => row.customer_name === 'Synthetic Stale Quote');
        cy.writeFile('.artifacts/cypress/stale-quote-observation.json', changed);
        cy.wrap(changed).should('have.length', 0);
      });
    });
  });
});
